// And groups predicates with the AND operator between them.
func And(predicates ...predicate.NovelVolume) predicate.NovelVolume {
	return predicate.NovelVolume(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.NovelVolume) predicate.NovelVolume {
	return predicate.NovelVolume(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.NovelVolume) predicate.NovelVolume {
	return predicate.NovelVolume(sql.NotPredicates(p))
}
